import {calculate,number,VERSION} from './calculations.js';
import {tools} from './tools.js';
import {guides,lessons,glossary} from './learning.js';
const $=id=>document.getElementById(id);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n===0?'0':Math.abs(n)<.00001||Math.abs(n)>=1e9?n.toExponential(5).replace('.',','):new Intl.NumberFormat('pt-BR',{maximumSignificantDigits:6}).format(n);
let current=tools[0],last=null,lastInputs=null,area='Todas',timer;
function catalog(){const query=normalize($('search').value),level=$('level').value;const found=tools.filter(t=>(area==='Todas'||t.area===area)&&(level==='Todos'||t.level===level)&&normalize(t.name+' '+t.desc+' '+t.level).includes(query));$('catalog').innerHTML=['Elétrica','Eletrônica'].map(a=>{const group=found.filter(t=>t.area===a);return group.length?`<div class="group-label">${a.toUpperCase()}</div>`+group.map(t=>`<button class="tool-button ${t.id===current.id?'selected':''}" data-tool="${t.id}" aria-pressed="${t.id===current.id}"><span class="tool-icon" aria-hidden="true">${t.symbol}</span><span>${t.name}${t.level==='Avançado'?'<small class="advanced-label">AVANÇADO</small>':''}</span></button>`).join(''):'';}).join('');$('empty').hidden=found.length>0;}
function fields(values){$('fields').innerHTML=current.fields.map(f=>`<div class="field"><label for="input-${f.key}">${f.label}</label><div class="input-wrap">${f.options?`<select id="input-${f.key}" name="${f.key}">${f.options.map(([v,l])=>`<option value="${v}" ${v===(values?.[f.key]??f.value)?'selected':''}>${l}</option>`).join('')}</select>`:`<input id="input-${f.key}" name="${f.key}" type="text" inputmode="decimal" value="${escape(values?.[f.key]??f.value)}" ${f.hint?`aria-describedby="hint-${f.key}"`:''} autocomplete="off"><span class="unit">${f.unit}</span>`}</div>${f.hint?`<span class="hint" id="hint-${f.key}">${f.hint}</span>`:''}</div>`).join('');}
function inputValues(){return Object.fromEntries(new FormData($('calc-form')));}
function resetResult(message='Preencha os dados e calcule para conferir o resultado.'){last=null;lastInputs=null;$('result').innerHTML=`<p class="placeholder">${escape(message)}</p>`;$('formula').textContent='—';$('steps').innerHTML='';$('note').textContent='As hipóteses do modelo aparecem após o cálculo.';$('source').textContent=current.source.label;$('source').href=current.source.url;$('copy').disabled=$('print').disabled=true;$('result-status').textContent='AGUARDANDO CÁLCULO';}
function renderResult(result,values,status){last=result;lastInputs=values;const [main,...others]=result.values;$('result').innerHTML=(result.warnings??[]).map(w=>`<p class="model-warning" role="status">${escape(w)}</p>`).join('')+`<div class="primary-result"><div class="label">${main.label}</div><div class="primary-value">${fmt(main.value)} <small>${main.unit}</small></div><span class="precision">Modelo ${VERSION} · até 6 algarismos significativos</span></div>`+others.map(r=>`<div class="secondary-result"><span>${r.label}</span><strong>${fmt(r.value)} ${r.unit}</strong></div>`).join('');$('formula').textContent=result.formula;$('steps').innerHTML=result.steps.map(s=>`<li>${escape(s)}</li>`).join('');$('note').textContent=result.note;$('source').textContent=current.source.label;$('source').href=current.source.url;$('copy').disabled=$('print').disabled=false;$('result-status').textContent=result.warnings?.length?'VERIFIQUE AS HIPÓTESES':status;$('error').hidden=true;}
function run(status='CÁLCULO ATUALIZADO'){try{const values=inputValues(),result=calculate(current.id,values);renderResult(result,values,status);return result;}catch(e){resetResult('O cálculo não foi concluído. Confira os dados de entrada.');$('error').textContent=e.message;$('error').hidden=false;throw e;}}
function showView(view){for(const [section,nav] of [['bench','bench-nav'],['references','reference-nav'],['materials','materials-nav']]){$(section).hidden=section!==view;$(nav).classList.toggle('nav-active',section===view);}}
function showBench(){showView('bench');history.replaceState(null,'',`#${current.id}`);}
function explain(){const g=guides[current.id];$('explanation').innerHTML=`<div class="explanation-title"><h3>Entenda este cálculo</h3><span class="area-tag">${current.level}</span></div><div class="guide-grid"><section><h4>O que o modelo representa</h4><p>${escape(g.concept)}</p><h4>Como preencher e interpretar</h4><p>${escape(g.use)}</p></section><section><h4>Exemplo resolvido</h4><p>${escape(g.example)}</p><h4>Erro comum a evitar</h4><p>${escape(g.pitfall)}</p></section></div><div class="related-lessons">${lessons.filter(l=>l.tools.includes(current.id)).map(l=>`<button class="lesson-link" data-lesson="${l.id}">Estudar: ${escape(l.title)}</button>`).join('')}</div>`;}
function select(id){current=tools.find(t=>t.id===id)??tools[0];showBench();$('tool-area').textContent=current.area+' · '+current.level;$('tool-name').textContent=current.name;$('tool-desc').textContent=current.desc;fields();catalog();explain();run('EXEMPLO CALCULADO');history.replaceState(null,'',`#${current.id}`);}
$('catalog').addEventListener('click',e=>{const b=e.target.closest('[data-tool]');if(b)select(b.dataset.tool);});
document.querySelectorAll('[data-area]').forEach(b=>b.addEventListener('click',()=>{area=b.dataset.area;document.querySelectorAll('[data-area]').forEach(x=>x.classList.toggle('active',x===b));catalog();}));
$('search').addEventListener('input',catalog);
$('level').addEventListener('change',catalog);
$('calc-form').addEventListener('submit',e=>{e.preventDefault();try{run();}catch{}});
$('calc-form').addEventListener('input',()=>{resetResult('Dados alterados. Calcule novamente para atualizar o resultado.');$('error').hidden=true;});
$('example').addEventListener('click',()=>{fields();run('EXEMPLO CALCULADO');});
$('clear').addEventListener('click',()=>{const values=Object.fromEntries(current.fields.map(f=>[f.key,f.options?f.value:'']));fields(values);resetResult();$('error').hidden=true;$('fields').querySelector('input,select')?.focus();});
$('bench-nav').addEventListener('click',showBench);
$('reference-nav').addEventListener('click',()=>{showView('references');history.replaceState(null,'','#references');});
$('materials-nav').addEventListener('click',()=>openMaterials());
function normalize(text){return String(text).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function renderLessons(){const query=normalize($('material-search').value),filter=$('material-area').value;const found=lessons.filter(l=>(filter==='Todas'||l.area===filter)&&normalize(l.title+' '+l.paragraphs.join(' ')+' '+l.level).includes(query));$('lesson-list').innerHTML=found.map(l=>`<details class="lesson" id="lesson-${l.id}"><summary><span class="lesson-title"><span class="eyebrow">${l.area} · ${l.level} · ${l.minutes} MIN</span><strong>${escape(l.title)}</strong></span><span class="expand-symbol" aria-hidden="true">+</span></summary><div class="lesson-body">${l.paragraphs.map(p=>`<p>${escape(p)}</p>`).join('')}<section class="exercise"><h4>Exercício para conferir</h4><p>${escape(l.exercise)}</p><details><summary>Ver resolução</summary><p>${escape(l.answer)}</p></details></section><h4>Aplicar na bancada</h4><div class="related-lessons">${l.tools.map(id=>`<button class="lesson-link" data-calc="${id}">${escape(tools.find(t=>t.id===id).name)}</button>`).join('')}</div><h4>Fontes para aprofundar</h4><div class="reading-links">${[...new Map(l.tools.map(id=>{const s=tools.find(t=>t.id===id).source;return [s.url,s];})).values()].map(s=>`<a href="${s.url}" target="_blank" rel="noopener noreferrer">${escape(s.label)}</a>`).join('')}</div></div></details>`).join('');$('material-empty').hidden=found.length>0;}
function openMaterials(id){showView('materials');history.replaceState(null,'',id?`#materials=${id}`:'#materials');if(id){$('material-search').value='';$('material-area').value='Todas';renderLessons();const detail=$('lesson-'+id);if(detail){detail.open=true;detail.scrollIntoView({behavior:'smooth',block:'start'});}}}
$('material-search').addEventListener('input',renderLessons);$('material-area').addEventListener('change',renderLessons);
document.addEventListener('click',e=>{const lesson=e.target.closest('[data-lesson]'),calc=e.target.closest('[data-calc]');if(lesson)openMaterials(lesson.dataset.lesson);if(calc){select(calc.dataset.calc);$('tool-name').scrollIntoView({behavior:'smooth',block:'start'});}});
$('glossary').innerHTML=glossary.map(([term,definition])=>`<div><dt>${escape(term)}</dt><dd>${escape(definition)}</dd></div>`).join('');
renderLessons();document.querySelector('.count').textContent=tools.length;
$('reference-list').innerHTML=tools.map(t=>`<article class="reference-card"><div><h3>${t.name}</h3><p>${t.desc}</p></div><a href="${t.source.url}" target="_blank" rel="noopener noreferrer">${t.source.label}</a></article>`).join('');
function reportText(){return ['ENGENHO — '+current.name,'Versão '+VERSION,new Date().toLocaleString('pt-BR'),'', 'DADOS',...current.fields.map(f=>`${f.label}: ${lastInputs[f.key] === '' ? 'sem carga' : (lastInputs[f.key] ?? 'sem carga')} ${f.unit||''}`),'','RESULTADOS',...last.values.map(r=>`${r.label}: ${fmt(r.value)} ${r.unit}`),'','FÓRMULA',last.formula,...last.steps,'','HIPÓTESES',last.note,'',current.source.label,current.source.url].join('\n');}
function toast(text){clearTimeout(timer);$('toast').textContent=text;$('toast').hidden=false;timer=setTimeout(()=>$('toast').hidden=true,3500);}
$('copy').addEventListener('click',async()=>{if(!last)return;try{await navigator.clipboard.writeText(reportText());toast('Resultado e memória copiados.');}catch{toast('A cópia foi bloqueada pelo navegador. Use o relatório para selecionar o texto.');}});
$('print').addEventListener('click',()=>{if(!last)return;const date=new Date().toLocaleString('pt-BR');$('print-report').innerHTML=`<h1>Engenho · Relatório de cálculo</h1><h2>${current.name}</h2><p>Gerado em ${date} · Modelo ${VERSION}</p><p>Projeto: ____________________________________</p><p>Responsável pela revisão: _____________________________</p><section><h2>Dados de entrada</h2><table><thead><tr><th>Grandeza</th><th>Valor</th><th>Unidade</th></tr></thead><tbody>${current.fields.map(f=>`<tr><td>${f.label}</td><td>${escape(f.options?f.options.find(([v])=>v===lastInputs[f.key])?.[1]:lastInputs[f.key] === '' ? 'Sem carga' : (lastInputs[f.key] ?? 'Sem carga'))}</td><td>${f.unit||''}</td></tr>`).join('')}</tbody></table></section><section><h2>Resultados calculados</h2><table><thead><tr><th>Grandeza</th><th>Valor</th><th>Unidade</th></tr></thead><tbody>${last.values.map(r=>`<tr><td>${r.label}</td><td>${fmt(r.value)}</td><td>${r.unit}</td></tr>`).join('')}</tbody></table></section><section><h2>Memória de cálculo</h2><code>${escape(last.formula)}</code><ol>${last.steps.map(s=>`<li>${escape(s)}</li>`).join('')}</ol></section><section><h2>Hipóteses e limites</h2><p>${escape(last.note)}</p><p>Dados de entrada informados pelo usuário. Resultados derivados do modelo; aplicação, conformidade e decisões de projeto dependem de revisão profissional.</p><p>Referência: ${current.source.label}</p><a href="${current.source.url}">${current.source.url}</a></section>`;window.print();});
if(document.modelContext?.registerTool){try{const lifecycle=new AbortController();Promise.resolve(document.modelContext.registerTool({name:'calculate_engineering_tool',title:'Calcular na bancada Engenho',description:'Seleciona uma calculadora, preenche os dados e calcula usando o mesmo modelo da interface. Unidades e campos disponíveis no catálogo visível.',inputSchema:{type:'object',properties:{toolId:{type:'string',enum:tools.map(t=>t.id)},inputs:{type:'object',additionalProperties:{type:['string','number']}}},required:['toolId','inputs'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||!tools.some(t=>t.id===input.toolId)||!input.inputs||typeof input.inputs!=='object')throw Error('Ferramenta ou entradas inválidas.');const tool=tools.find(t=>t.id===input.toolId);const allowed=tool.fields.map(f=>f.key);if(Object.keys(input.inputs).some(k=>!allowed.includes(k)))throw Error('Campo desconhecido.');if(allowed.some(k=>k!=='rl'&&!(k in input.inputs)))throw Error('Faltam dados de entrada.');const result=calculate(tool.id,input.inputs);select(tool.id);fields(input.inputs);renderResult(result,input.inputs,'CÁLCULO ATUALIZADO');return result;}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}catch{}}
const initial=location.hash.slice(1);select(initial);if(initial==='references'){showView('references');history.replaceState(null,'','#references');}else if(initial.startsWith('materials'))openMaterials(initial.split('=')[1]);
